(function(){'use strict';function refresh(){const home=!location.search&&(!location.hash||location.hash==='#main'||location.hash==='#start-here');document.body.classList.toggle('beginner-home',home);const entry=document.getElementById('start-here');if(entry)entry.hidden=!home;const start=document.getElementById('nav-start');if(start)start.setAttribute('aria-current',home?'page':'false');if(home)for(const id of ['explore','vendor-catalog','timeline','evaluation','learn','coverage'])document.getElementById('nav-'+id)?.setAttribute('aria-current','false');}globalThis.ModelAtlasEntry={refresh};refresh();window.addEventListener('popstate',refresh);window.addEventListener('hashchange',refresh);})();
